changeSet.sql:
update kb_email_template set strtext='{text} 
File info:
${file-title}
${file-metadata}
${file-library-url}', 
subject='RPDD - ${file-title}',
title='Workflow Alert (task post termination / timeout)' where xkey='workflow-notification';

update kb_email_template set state=4 where xkey ='welcome';
update kb_email_template set state=4 where title like '%former%';
update kb_email_template set state=4 where title like '%equires%';


				update kb_email_template set state=4 where xkey like '%standard';

				update kb_email_template set title = 'Password Reset - Admin' where title like 'Admin %';
				update kb_email_template set title = 'Password Reset - User' where title like 'User %';

				update kb_email_template set strtext= E'${person-displayname}, 

The Admin user has sent you this link to reset your account password.

 Please visit the link below and follow theinstructions: 
${password-reset-url}

For security reasons, this link will expire in 72 hours after your initial request was made.' where xkey like 'admin-sends-%' and lang='en';
				update kb_email_template set strtext= E'${person-displayname}, 

Your database export is ready. 

You can download it as a zip file from this link: 
${database-export-url} 

For security reasons, this link will expire in 10 days after your initial request was made.' where xkey like 'db-exp%' and lang='en';
				update kb_email_template set strtext= E'${person-displayname}

We have received your request to send your  <b>${application-name}</b>  username. 

We have the following user account associated to the email address and phone 

<b>User Account</b>.  ${person-username}
<b>Email </b>.  ${person-email-address} 
<b>Phone</b>. ${person-phone-last-four-digits}.' where xkey like 'forgot-user%' and lang='en';
				update kb_email_template set strtext= E'${person-displayname}, 

We have received your request to reset your account password.


Please visit the link below and follow the instructions to reset your password
: ${password-reset-url}

 For security reasons, this link will expire in 72 hours after your initial request was made.
 If you did not request to reset your password, you can safely ignore this email.' where xkey like 'forgot-password%' and lang='en';
				update kb_email_template set strtext= E'${from-displayname} has assigned the following task: 

Task: ${task-name} 
File: ${file-title}
${file-metadata}

Comment: ${comment}

---
Please go to My Tasks at 
 ${my-tasks-url} 
 to retrieve additional information about this file.' where xkey like 'assign-task%' and lang='en';
				update kb_email_template set strtext= E'New file in Pending Tasks: 
${file-title}.

Please go to Pending Tasks Section at 
 ${pending-tasks-url} 
to view or take it. 

From: ${previous-task-user} 
Previous Task: ${previous-task}
 Previous Task resolution: ${previous-task-action} 
Comment: ${comment}' where xkey like 'pending-task%' and lang='en';
				update kb_email_template set strtext= E'The following task has timeout:

${task-name}
${file-title}
The file has been taken from your Workspace and moved to the next task defined in the workflow.' where xkey like 'timeout-task%' and lang='en';
				update kb_email_template set strtext= E'Task execution timeout.

Task: ${task-name} 
File: ${file-title}
${file-metadata}' where xkey like 'workflow-notification-timeout%' and lang='en';

				update kb_email_template set strtext= E'${person-displayname} has published: 

${file-title} 
${file-attributes} 
To retrieve additional information view the file published at
${file-library-url}
or go to Library at 
${library-url}' where xkey like '%rule-publish-domain%' and lang='en';
				update kb_email_template set strtext= E'${person-displayname} has published: 

${file-title} 
${file-attributes} 
To retrieve additional information view the file published at
${file-library-url}
or go to Library at 
${library-url}' where xkey like '%rule-publish-user%' and lang='en';

update kb_email_template set title = 'Rule Action' where xkey like '%action-rule';
update kb_email_template set title = 'Task due date timeout' where xkey like 'timeout-task';
update kb_email_template set title = 'Workflow Post Termination event Send to' where xkey like '%notification-timeout';
update kb_email_template set state=4 where title like '%uevo Dominio';

update kb_email_template set xkey='welcome_compliance' where xkey = 'welcome_compliance_monitoring';
update kb_email_template set title='Workflow Task Post Termination (Send to)' where xkey = 'workflow-notification';
 update kb_email_template set title='Workflow Task timeout (running or pending)' where xkey = 'workflow-notification-timeout';

alter table po_portalobject add column if not exists key character varying(256);

alter table po_site add column if not exists owner_id bigint references users(id) on delete restrict;
alter table po_site add column if not exists footer_page_section  bigint references po_page_section on delete restrict;
alter table po_site add column if not exists topbar_page_section  bigint references po_page_section on delete restrict;
alter table po_site add column if not exists site_menu text;


alter table po_page 			drop constraint if exists po_id_fk;
alter table po_page_section 	drop constraint if exists po_id_fk;
alter table po_area				drop constraint if exists po_id_fk;
alter table po_block			drop constraint if exists po_id_fk;



alter table po_page 			add constraint     po_id_fk foreign key(po_id) references po_portalobject(id) on delete cascade;
alter table po_area 			add constraint     po_id_fk foreign key(po_id) references po_portalobject(id) on delete cascade;
alter table po_page_section 	add constraint     po_id_fk foreign key(po_id) references po_portalobject(id) on delete cascade;
alter table po_block 			add constraint     po_id_fk foreign key(po_id) references po_portalobject(id) on delete cascade;

	drop table if exists po_block_contact;
	drop table if exists po_block_banners;
	drop table if exists po_block_content_list;
	drop table if exists po_block_cumpleanos;
	drop table if exists po_block_footer;
	drop table if exists po_block_search_external;
	drop table if exists po_block_search_contentbblock;
	drop table if exists po_block_search_contentblock;
	drop table if exists po_contentblock;
	drop table if exists po_block_wall_viewer;
	drop table if exists po_block_wallviewer;
	drop table if exists po_block_wall_viewer;
	drop table if exists po_block_list;
	drop table if exists po_block_view_recent_list;

	alter table po_block drop column if exists quantity_visible;
	alter table po_block drop column if exists title_visible;
	alter table po_block drop column if exists intro_visible;
 	alter table po_block drop column if exists block_menu_enabled;
 	alter table po_block drop column if exists description;
 	alter table po_block drop column if exists block_body_style;


					alter table po_portalobject drop column  if exists parent_id;

					 alter table po_site drop constraint if exists po_site_footer_page_section_fkey1;
					 alter table po_site drop constraint if exists po_site_footer_page_section_fkey2;
					 alter table po_site drop constraint if exists po_site_footer_page_section_fkey3;
					 alter table po_site drop constraint if exists  po_site_owner_id_fkey1;
					 alter table po_site drop constraint if exists  po_site_owner_id_fkey2;
					 alter table po_site drop constraint if exists  po_site_owner_id_fkey3;
					 alter table po_site drop constraint if exists  po_site_owner_id_fkey4;
					 alter table po_site drop constraint if exists po_site_topbar_area_fkey;
					 alter table po_site drop constraint if exists po_site_topbar_page_section_fkey1;
					 alter table po_site drop constraint if exists po_site_topbar_page_section_fkey2;
					 alter table po_site drop constraint if exists po_site_topbar_page_section_fkey3;
					 alter table po_site drop constraint if exists site_fk;

 					 alter table po_page drop constraint if exists page_fk;
 					 alter table po_page_section drop constraint if exists po_page_section_fk;

 					 alter table po_area drop constraint if exists po_area_page_section_fk;
 					 alter table po_area add constraint po_area_page_section_fk foreign key(page_section_id) references po_page_section(po_id) on delete cascade;

 					 alter table po_block drop constraint if exists area_fk;
					 alter table po_block drop constraint if exists block_fk;
 					 alter table po_block drop constraint if exists po_area_fk;
				    alter table po_block add constraint po_area_fk  foreign key (area_id) references po_area(po_id) on delete cascade;

alter table po_page_section add column if not exists ptab integer default 0;
alter table po_area  add column if not exists ptab integer default 0;
alter table po_block  add column if not exists ptab integer default 0;

alter table po_page_section add column if not exists tabs text;
alter table po_page add column if not exists tabs text;
alter table po_block add column if not exists tabs text;

alter table po_block add column if not exists headerpanel boolean default false;
alter table po_area add column if not exists headerpanel boolean default false;
alter table po_page_section add column if not exists headerpanel boolean default false;

drop table if exists kb_support_ticket;
CREATE TABLE kb_support_ticket ( id bigint primary key, user_id bigint not null references users(id) REFERENCES users(id) ON DELETE RESTRICT, subject character varying(512), text text, creationdate timestamp with time zone default now(), lastmodifieddate timestamp with time zone default now(), lastmodifieduser bigint references users(id) ON DELETE SET NULL, state integer default 1, priority integer default 1, domain_id bigint not null references domain(id) ON DELETE CASCADE, kfile bigint references kfile(resource_id) ON DELETE RESTRICT, context text, error_count integer default 0,
deliverystatus integer default 0, deliverymsg character varying(512) );
create index kb_support_creation_date on kb_support_ticket(domain_id, creationdate desc);

delete from kb_cronjob where parameter like '%SupportTicket%';;
insert into kb_cronjob (id, lastmodifieduser, name, description, cronexpression, clazz, parameter) values ((select nextval('objectid_sequence')), (select id from users where username='root@kbee'), 'Support ticket submit executes once a minute (tickets PEMDING with error_count <= 3)', 'SupportTicketsSubmitterCommand', '25 * * * * *', 'com.novamens.kbee.command.CommandExecutionJob', 'command=SupportTicketsSubmitterCommand');
insert into kb_cronjob (id, lastmodifieduser, name, description, cronexpression, clazz, parameter) values ((select nextval('objectid_sequence')), (select id from users where username='root@kbee'), 'Support ticket submit executes once a day (tickets PEMDING with error_count <= 6)', 'SupportTicketsSubmitterCommand', '45 45 6 * * *', 'com.novamens.kbee.command.CommandExecutionJob', 'command=SupportTicketsSubmitterDailyCommand');

CREATE TABLE kb_resource_tag (
	id bigint NOT NULL,
	name character varying(256),
	creationdate timestamp with time zone DEFAULT now(),
	lastmodifieddate timestamp with time zone DEFAULT now(),
	lastmodifieduser bigint,
	domain_id bigint,
	alias character varying(256),
	multiple boolean default true,
	state integer DEFAULT 1,
	createuser bigint,
	type integer DEFAULT 1 NOT NULL
);
CREATE TABLE kb_template_resource_tag (
	template_id bigint NOT NULL,
	tag_id bigint NOT NULL,
	"position" integer
);
ALTER TABLE ONLY kb_resource_tag
	ADD CONSTRAINT resourcetag_pkey PRIMARY KEY (id);
ALTER TABLE ONLY kb_resource_tag
	ADD CONSTRAINT resourcetag_createuser_fkey FOREIGN KEY (createuser) REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE ONLY kb_resource_tag
	ADD CONSTRAINT resourcetag_domain_id_fkey FOREIGN KEY (domain_id) REFERENCES domain(id) ON DELETE CASCADE;
ALTER TABLE ONLY kb_template_resource_tag
	ADD CONSTRAINT template_resourcetag_pkey PRIMARY KEY (template_id, tag_id);
ALTER TABLE ONLY kb_template_resource_tag
	ADD CONSTRAINT resourcetag_fk FOREIGN KEY (tag_id) REFERENCES kb_resource_tag(id) ON DELETE RESTRICT;
ALTER TABLE ONLY kb_resource_tag
	ADD CONSTRAINT resourcetag_lastmodifieduser_fkey FOREIGN KEY (lastmodifieduser) REFERENCES users(id) ON DELETE RESTRICT;

alter table contentresource add tag_id bigint;
ALTER TABLE ONLY contentresource
ADD CONSTRAINT contentresource_tag_id_fkey FOREIGN KEY (tag_id) REFERENCES kb_resource_tag(id) ON DELETE RESTRICT;
